/* Configuration-driven entity preview. Fixture inputs are isolated from live records. */
const ep={tab:'earnings',month:'2026-10',selection:'assigned',rider:'RDR-DEMO',path:[],query:''};
const epToday='2026-10-19', epRoot=document.querySelector('#entity-payout');
const epDate=d=>new Date(d+'T00:00:00Z'),epISO=d=>d.toISOString().slice(0,10),epAdd=(d,n)=>{const a=epDate(d);a.setUTCDate(a.getUTCDate()+n);return epISO(a)};
const epLabel=d=>epDate(d).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'});
const epRange=(a,b)=>a===b?epLabel(a):epLabel(a)+' – '+epLabel(b);
const epMonth=m=>epDate(m+'-01').toLocaleDateString('en-IN',{month:'long',year:'numeric',timeZone:'UTC'});
const epMoney=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:1,maximumFractionDigits:1}).format(n);
const epName=k=>sharedKeys.find(x=>x.id===k||x.formulaKey===k)?.name||k.replaceAll('_',' ');
const epSum=xs=>xs.reduce((a,x)=>a+(x.amount||0),0);
const epRound=n=>Math.round((n+Number.EPSILON)*100)/100;
function epWindow(s,d){if(s.period==='Daily')return {start:d,end:d};if(s.period==='Weekly'){const start=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].indexOf(s.weekStart||'Monday');const a=epAdd(d,-((epDate(d).getUTCDay()-start+7)%7));return {start:a,end:epAdd(a,6)}}const date=epDate(d),day=Number(s.cycleStart||1);let y=date.getUTCFullYear(),m=date.getUTCMonth();if(date.getUTCDate()<day)m--;const a=new Date(Date.UTC(y,m,day)),b=new Date(Date.UTC(y,m+1,day-1));return {start:epISO(a),end:epISO(b)}}
function epWindows(s,month){const end=epISO(new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0))),out=new Map();for(let d=month+'-01';d<=end;d=epAdd(d,1)){const w=epWindow(s,d);if(w.end.startsWith(month))out.set(w.start,w)}return [...out.values()]}
function epRider(){return users.find(u=>u.id===ep.rider)||users[0]}
function epTemplates(){const u=epRider();const ids=[...new Set(assignmentsForUser(u).map(a=>a.template))];const applied=ids.map(template).filter(Boolean);if(ep.previewTemplate){const t=template(ep.previewTemplate);return applied.filter(x=>x.structure!==t?.structure).concat(t?[t]:[])}return applied}
function epDependencyTemplates(){return epTemplates()}
function epEffective(t){const s=structure(t.structure);return t.components.map(c=>{const d=s.components.find(d=>d.id===c.id)||c;return {...c,description:d.description??c.description??'',valueFormat:d.valueFormat||'Amount',display:d.display||c.display||{}}})}
function epDisplay(c,k){return c.display?.labels?.[k]?.trim()||epName(k)}
function epValueLabel(c){return c.display?.valueLabel?.trim()||'Value'}
function epUnitsLabel(c){return c.display?.unitsLabel?.trim()||'Units'}
function epUnitIdLabel(c){return c.display?.unitIdLabel?.trim()||'Unit ID'}
function epEffect(c){return c.effect==='Deduct'?'Deduction':'Addition'}

function epRecords(w){const records=[];for(let d=w.start;d<=w.end&&d<=epToday;d=epAdd(d,1))for(let i=1;i<=6+(epDate(d).getUTCDate()%5);i++)records.push({shipment_id:d+'-S'+String(i).padStart(3,'0'),rider_id:epRider().id,delivered_at:d,shipment_type:['COD','Prepaid','BFSI'][i%3],weight_kg:1+i%7,weight_category:i%3?'Standard':'Heavy',status:i%9?'Delivered':'Attempted',rank:1+i%2});return records}
function epMetrics(w,rs){let attendance=0,hours=0,days=0;for(let d=w.start;d<=w.end&&d<=epToday;d=epAdd(d,1)){days++;const h=epDate(d).getUTCDate()%3===1?4:7;hours+=h;if(h>=5)attendance++}return {shipment_count:rs.filter(r=>r.status==='Delivered').length,attendance_days:attendance,attendance_hours:hours,absent_days:days-attendance,total_km:days*18,closure:.96}}
function epConditions(c,metrics){return (c.filters||[]).map(f=>({...f,actual:metrics[f.key],passed:metrics[f.key]==null?null:compare(metrics[f.key],f.op,f.value)}))}
function epEvaluate(t,w,context={active:new Set(),cache:new Map()}){const contextKey=t.id+'|'+w.start+'|'+w.end;if(context.cache.has(contextKey))return context.cache.get(contextKey);if(context.active.has(contextKey))throw Error('Circular payout output reference.');context.active.add(contextKey);const s=structure(t.structure),rs=epRecords(w),metrics=epMetrics(w,rs),outputs={},results=[];let running=0;for(const c of epEffective(t)){const conditions=epConditions(c,metrics);let amount=0,records=[],error='',inputs={},unitOutputs=c.basis==='Per Unit'?Object.fromEntries(rs.map(r=>[r[state.units.find(u=>u.id===c.unit)?.unitId],0])):null;try{
 scopeCheck({...s,components:epEffective(t)},c,results.length);
 if(conditions.some(f=>f.passed===null))throw Error('Condition data unavailable for this preview.');
 const pass=!conditions.length||(c.filterJoin==='OR'?conditions.some(f=>f.passed):conditions.every(f=>f.passed));
 const base={...formulaScope(c.keys||[],metrics),...outputs,running_payout:running,__resolveOutput:(token,record)=>{const target=outputTarget(token,s);if(!target||!compatibleStructure(s,target.s))throw Error('Output requires the same evaluation window.');const matches=epDependencyTemplates().filter(x=>x.structure===target.s.id);if(matches.length!==1)throw Error('An applicable template is required for '+target.s.name);const dependency=epEvaluate(matches[0],w,context);if(dependency.some(r=>r.error))throw Error('Referenced earnings are unavailable.');if(target.perUnit){if(!record||record.unit!==target.c.unit)throw Error('Unit context is required.');return readUnitOutput(dependency.find(r=>r.c.id===target.c.id)?.unitOutputs,record.id)}return target.c?dependency.find(r=>r.c.id===target.c.id)?.amount*(target.c.effect==='Deduct'?-1:1):epSum(dependency)}};
 if(!pass){amount=0}else if(c.basis==='Per Unit'){
 const unit=state.units.find(u=>u.id===c.unit);if(!unit?.sample)throw Error('No sample records for this registered unit.');
 records=rs.map(r=>{const eligible=!c.unitFilterKey||compare(r[c.unitFilterKey],c.unitFilterOp,c.unitFilterValue);const match=c.lookup==='Flat'?null:(c.rates||[]).find(x=>lookupMatches(c,x,r));if(eligible&&c.lookup!=='Flat'&&!match)throw Error('A sample unit has no matching lookup value.');const value=Number(match?.value??c.defaultValue),vars={...base,...r,value,__resolveOutput:token=>{const local=results.find(result=>result.c.basis==='Per Unit'&&token===unitComponentKey(result.c));if(local)return readUnitOutput(local.unitOutputs,r[unit.unitId]);return base.__resolveOutput(token,{unit:c.unit,id:r[unit.unitId]})}};const n=eligible?formulaEval(c.formula,vars):0;unitOutputs[r[unit.unitId]]=n;return {id:r[unit.unitId],attributes:r,value,amount:epRound(n*(c.effect==='Deduct'?-1:1)),eligible,inputs:vars,match}});amount=epSum(records);
 }else{inputs={...base,value:Number(c.defaultValue)};amount=formulaEval(c.formula,inputs)*(c.effect==='Deduct'?-1:1)}
 if(!Number.isFinite(amount))throw Error('Calculation is unavailable.');
 }catch(e){error=e.message;amount=null;records=[];unitOutputs=null}
 if(amount!==null){outputs[periodComponentKey(s,c)]=amount*(c.effect==='Deduct'?-1:1);outputs[c.id]=amount*(c.effect==='Deduct'?-1:1);outputs[componentOutputKey(c)]=amount*(c.effect==='Deduct'?-1:1);running+=amount}else {outputs[c.id]=undefined;outputs[componentOutputKey(c)]=undefined;running=NaN}
 results.push({c,t,s,w,amount:amount===null?null:epRound(amount),records,conditions,inputs,error,unitOutputs});
 }context.active.delete(contextKey);context.cache.set(contextKey,results);return results}
function epData(){const out=[];for(const t of epTemplates()){const s=structure(t.structure);if(!s)continue;for(const w of epWindows(s,ep.month)){if(w.end>epToday)continue;out.push(...epEvaluate(t,w))}}return out}
function epButton(label,amount,sub,action,index){return `<button class="ep-row" data-ep="${action}" data-i="${index}"><span><b>${esc(label)}</b>${sub?`<small>${esc(sub)}</small>`:''}</span><span class="ep-amount ${amount<0?'negative':''}">${amount===null?'Pending':epMoney(amount)} <i>›</i></span></button>`}
function epTable(heads,rows){return `<div class="ep-table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function epKey(v){return typeof v==='object'&&v!==null?(v.max==='+'?`${v.min}+`:`${v.min}–${v.max}`):String(v)}
function epBand(c,d,v){const suffix=c.display?.units?.[d.name]||state.units.find(u=>u.id===c.unit)?.attributes.find(a=>a.name===d.name)?.unit||'';return epKey(v)+(suffix?' '+suffix:'')}
function epValue(c,v){const n=new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(Number(v));return c.valueFormat==='Percentage'?n+'%':c.valueFormat==='Number'?n:'₹'+n}

function epCycle(s){return s.period==='Weekly'?(s.weekStart||'Monday')+' to '+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].indexOf(s.weekStart||'Monday')+0)%7]:s.period==='Monthly'?(Number(s.cycleStart||1)===1?'1st to last day':`${s.cycleStart} to ${Number(s.cycleStart)-1} of next month`):'Each day'}
function epCompareKeys(a,b){for(let i=0;i<Math.max(a.length,b.length);i++){const x=a[i],y=b[i];const diff=x&&y&&typeof x==='object'&&typeof y==='object'?Number(x.min)-Number(y.min):String(x??'').localeCompare(String(y??''),undefined,{numeric:true});if(diff)return diff;}return 0;}
function epSortedRates(c){return [...(c.rates||[])].sort((a,b)=>epCompareKeys(a.keys,b.keys));}
function epRateCards(){return epTemplates().map(t=>{const s=structure(t.structure);return `<section class="ep-block"><div class="ep-rate-heading"><span class="ep-period-tag">${esc(s.period)}</span></div>${epEffective(t).map(c=>`<details class="ep-card"><summary><span><b>${esc(c.name)}</b></span><span>⌄</span></summary><div class="ep-detail">${c.description?`<p>${esc(c.description)}</p>`:''}${c.basis==='Per Unit'&&c.lookup!=='Flat'?epTable([...lookupDimensions(c).map(d=>epDisplay(c,d.name)),epValueLabel(c)],epSortedRates(c).map(r=>[...r.keys.map((k,i)=>esc(epBand(c,lookupDimensions(c)[i],k))),esc(epValue(c,r.value))])):`<div class="ep-pair"><span>${esc(epValueLabel(c))}</span><b>${esc(epValue(c,c.defaultValue))}</b></div>`}${conditionCopy(c)?`<p>${esc(conditionCopy(c))}</p>`:''}</div></details>`).join('')}</section>`}).join('')||'<p class="ep-empty">No payout template is assigned to this rider.</p>'}
let epRows=[],epGroups=[],epActive=null;
function epConditionsUI(r){return r.conditions.length?`<h3>${r.c.filterJoin==='OR'?'Any condition required':'All conditions required'}</h3>${r.conditions.map(f=>`<details class="ep-condition"><summary>${esc(epDisplay(r.c,f.key))} ${esc(f.op)} ${esc(f.value)} <span class="${f.passed?'met':'negative'}">${f.passed===null?'Unavailable':f.passed?'Met':'Not met'}</span></summary><div class="ep-pair"><span>Actual ${esc(epDisplay(r.c,f.key))}</span><b>${esc(f.actual??'Unavailable')}</b></div></details>`).join('')}`:''}
function epDetail(r){epActive=r;epGroups=[];const dims=r.c.basis==='Per Unit'&&r.c.lookup!=='Flat'?lookupDimensions(r.c):[];
 if(r.c.basis==='Per Unit'){const grouped=new Map();for(const rec of r.records){const cells=dims.length?dims.map((a,i)=>rec.match?epBand(r.c,a,rec.match.keys[i]):String(rec.attributes[a.name])):['All units'];const key=JSON.stringify([cells,rec.eligible]);if(!grouped.has(key))grouped.set(key,{label:cells.join(' · '),cells,records:[],amount:0,value:rec.value,eligible:rec.eligible});const g=grouped.get(key);g.records.push(rec);g.amount=epRound(g.amount+rec.amount)}epGroups=[...grouped.values()].sort((a,b)=>epCompareKeys(a.records[0].match?.keys||a.cells,b.records[0].match?.keys||b.cells))}
 return `<div class="ep-section"><span class="ep-eyebrow">${esc(epRange(r.w.start,r.w.end))}</span><h2>${esc(r.c.name)}</h2><div class="ep-big ${r.amount<0?'negative':''}">${r.amount===null?'Pending':epMoney(r.amount)}</div>${r.c.description?`<p>${esc(r.c.description)}</p>`:''}</div>${r.error?`<p class="ep-alert">${esc(new URLSearchParams(location.search).get('embedded')==='1'?r.error:'Earnings are unavailable because some data is missing.')}</p>`:''}${conditionCopy(r.c)?`<div class="ep-section"><p>${esc(conditionCopy(r.c))}</p></div>`:''}${epConditionsUI(r)}${r.c.basis==='Per Unit'?`<h3>${esc(epUnitsLabel(r.c))}</h3>${epTable([...(dims.length?dims.map(d=>epDisplay(r.c,d.name)):['Group']),epValueLabel(r.c),epUnitsLabel(r.c),'Amount',''],epGroups.map((g,i)=>[...g.cells.map(esc),esc(epValue(r.c,g.value)),g.records.length,epMoney(g.amount),`<button class="ep-link" data-ep="units" data-i="${i}">View details</button>${g.eligible?'':'<small>Condition not met</small>'}`]))}`:`<div class="ep-section"><div class="ep-pair"><span>${esc(epValueLabel(r.c))}</span><b>${esc(epValue(r.c,r.c.defaultValue))}</b></div></div>`}`}
function epGroup(rows,key){const m=new Map();for(const r of rows){const k=key(r);if(!m.has(k))m.set(k,[]);m.get(k).push(r)}return [...m.values()]}
function epTotal(rows){return rows.some(r=>r.error)?null:epRound(epSum(rows))}
function epComponentGroups(all){return epGroup(all,r=>r.t.id+'|'+r.c.id)}
function epPeriodCount(rows){const n=new Set(rows.map(r=>r.w.start+'|'+r.w.end)).size;return n+' '+(rows[0].s.period==='Daily'?(n===1?'day':'days'):rows[0].s.period==='Weekly'?(n===1?'week':'weeks'):(n===1?'monthly period':'monthly periods'))}
function epEarnings(){const all=epData(),path=ep.path;
 if(!path.length)return `<button class="ep-hero" data-ep="month"><span>${esc(epMonth(ep.month))}</span><strong>${epMoney(epSum(all))}</strong><small>${ep.month===epToday.slice(0,7)?'Earnings so far':'Earnings'} <span>View components →</span></small></button><div class="ep-section"><h2>Your monthly earnings</h2><p>See what each component contributes, then explore its daily, weekly or monthly details.</p><div class="ep-note">Weekly and monthly periods appear in the month they end.</div>${all.some(r=>r.error)?'<p class="ep-alert">Some earnings are pending and are excluded from this total.</p>':''}</div>${epOpenCycles()}`;
 const groups=epComponentGroups(all);epRows=groups;
 if(path.length===1)return `<div class="ep-section"><span class="ep-eyebrow">${esc(epMonth(ep.month))}</span><h2>Your components</h2><div class="ep-big">${epMoney(epSum(all))}</div></div>${groups.map((rs,i)=>epButton(rs[0].c.name,epTotal(rs),'','component',i)).join('')||'<p class="ep-empty">No earnings available this month.</p>'}${all.some(r=>r.error)?'<p class="ep-alert">Net earnings excludes pending amounts.</p>':''}${epOpenCycles()}`;
 const rows=groups[path[1]];if(!rows)return '<p class="ep-empty">No earnings available.</p>';
 if(rows[0].s.period==='Monthly'&&rows.length===1)return epDetail(rows[0]);
 if(path.length===2)return `<div class="ep-section"><span class="ep-eyebrow">${esc(epMonth(ep.month))}</span><h2>${esc(rows[0].c.name)}</h2><div class="ep-big ${epSum(rows)<0?'negative':''}">${epTotal(rows)===null?'Pending':epMoney(epTotal(rows))}</div></div>${rows.map((r,i)=>epButton(epRange(r.w.start,r.w.end),r.amount,'','period',i)).join('')}`;
 return rows[path[2]]?epDetail(rows[path[2]]):'<p class="ep-empty">No earnings available.</p>'}
function epOpenCycles(){const rows=[];for(const t of epTemplates()){const s=structure(t.structure),w=epWindow(s,epToday);if(w.end>epToday&&w.end.startsWith(ep.month))for(const c of epEffective(t))rows.push(`<div class="ep-pair"><span>${esc(c.name)}<small>${esc(epRange(w.start,w.end))} · ${esc(s.name)}</small></span><span class="ep-badge">In progress</span></div>`)}return rows.length?`<div class="ep-section"><h3>In progress</h3><p>Not included in earnings yet.</p>${rows.join('')}</div>`:''}

function epRender(){epRoot.innerHTML=`<div class="ep-layout"><aside class="ep-sidebar"><a class="ep-brand" href="index.html?role=entity"><span>≡</span> Your earnings</a><a href="index.html?role=entity">Incentives</a><a class="selected" href="entity-payouts.html">Payouts</a><div class="ep-side-foot">${esc(epRider().name)}<br>${esc(epRider().id)}</div></aside><main class="ep-main"><div class="ep-top"><div><span class="ep-eyebrow">YOUR PAYOUTS</span><h1>A clear view of your earnings</h1></div></div><div class="ep-controls"><label>Select rider<select id="ep-rider">${users.map(u=>`<option value="${esc(u.id)}" ${ep.rider===u.id?'selected':''}>${esc(u.name)} · ${esc(u.id)}</option>`).join('')}</select></label></div><nav class="ep-tabs" aria-label="Payout views"><button data-ep="earnings" class="${ep.tab==='earnings'?'active':''}">Earnings</button><button data-ep="rate" class="${ep.tab==='rate'?'active':''}">Rate card</button></nav><div class="ep-content">${ep.tab==='earnings'?`<div class="ep-toolbar">${ep.path.length?'<button class="ep-link" data-ep="back">← Back</button>':'<span>Monthly overview</span>'}<label class="ep-month"><span class="sr-only">Month</span><select id="ep-month">${['2026-09','2026-10'].filter(m=>m<=epToday.slice(0,7)).map(m=>`<option value="${m}" ${ep.month===m?'selected':''}>${epMonth(m)}</option>`).join('')}</select></label></div>${epEarnings()}`:epRateCards()}</div></main></div>`}
function epUnitList(g){const dialog=document.querySelector('#unit-sheet');dialog.innerHTML=`<div class="ep-sheet-head"><div><span class="ep-eyebrow">${esc(epActive.c.name)}</span><h2>${esc(g.label)}</h2><p>${g.records.length} ${esc(epUnitsLabel(epActive.c))} · ${epMoney(g.amount)}</p></div><button data-ep="close" aria-label="Close unit details">×</button></div><label class="ep-search">${esc(epUnitIdLabel(epActive.c))}<input id="ep-search" placeholder="Search ${esc(epUnitIdLabel(epActive.c))}"></label><div id="ep-unit-list"></div>`;epShownGroup=g;epUnitRows('');if(!dialog.open)dialog.showModal()}
let epShownGroup=null;
function epUnitRows(query){const c=epActive.c,dims=c.lookup==='Flat'?[]:lookupDimensions(c),rs=epShownGroup.records.filter(r=>String(r.id).toLowerCase().includes(query.toLowerCase()));document.querySelector('#ep-unit-list').innerHTML=rs.length?epTable([epUnitIdLabel(c),...dims.map(d=>epDisplay(c,d.name)),epValueLabel(c),'Amount'],rs.map(r=>[esc(r.id),...dims.map(d=>esc(r.attributes[d.name])),esc(epValue(c,r.value)),`<details><summary>${epMoney(r.amount)}</summary>${c.description?`<p>${esc(c.description)}</p>`:''}${c.unitFilterKey?`<p>Condition: ${esc(epDisplay(c,c.unitFilterKey))} ${esc(c.unitFilterOp)} ${esc(c.unitFilterValue)}<br>Actual: ${esc(r.attributes[c.unitFilterKey])}<br>${r.eligible?'Met':'Not met'}</p>`:''}</details>`])):'<p class="ep-empty">No matching units.</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ep]');if(!b)return;const action=b.dataset.ep;if(action==='close'){document.querySelector('#unit-sheet').close();return}if(action==='units'){epUnitList(epGroups[Number(b.dataset.i)]);return}if(action==='back')ep.path.pop();else if(action==='rate'||action==='earnings'){ep.tab=action;ep.path=[]}else if(action==='month')ep.path=['components'];else if(['component','period'].includes(action))ep.path.push(Number(b.dataset.i));epRender()});
document.addEventListener('change',e=>{if(e.target.id==='ep-rider'){ep.rider=e.target.value;ep.path=[];epRender()}if(e.target.id==='ep-month'){ep.month=e.target.value;ep.path=[];epRender()}});
document.addEventListener('input',e=>{if(e.target.id==='ep-search')epUnitRows(e.target.value)});
epRender();
